def f(g):
    # find full-width separator row of uniform nonzero color
    H=len(g); W=len(g[0])
    sep=None
    for r in g:
        c=r[0]; 
        if c!=0 and all(x==c for x in r): sep=(r.index(c) if False else 0, c, r)
    if sep is None:
        for r in g:
            if len(set(r))==1 and r[0]!=0: sep=r
    i,c,rr=sep
    # move shape vertically toward separator, fill rest with background
    bg=g[0][0]
    out=[row[:] for row in g]; out[i]=[8]*W
    # shape cells = nonzero non-separator cells
    cells=[(r,col) for r in range(H) for col in range(W) if g[r][col]!=bg and g[r][col]!=c and out[r][col]==g[r][col]]
    rs=[r for r,_ in cells]; cols={col for _,col in cells}
    minr=max(0,min(rs)); maxr=max(rs)
    newi=i- (max(0,i-len(range(maxr-minr+1,0))))
    # simpler: place shape adjacent above separator, preserving shape bounds
    h=maxr-minr+1
    newtop=i-h
    if newtop<0: newtop=0
    # clear old shape
    for r in range(minr,maxr+1):
        for col in cols: out[r][col]=bg
    for dr in range(h):
        for col in cols:
            out[newtop+dr][col]=g[minr+dr][col]
    return out

